const checksum = (seed: string) => {
  const base = `${seed}meddatahub-synthetic-checksum`;
  let out = '';
  for (let i = 0; out.length < 64; i += 1) {
    out += Math.abs(
      (base.charCodeAt(i % base.length) + i * 37 + seed.length * 11) % 16,
    ).toString(16);
  }
  return out.slice(0, 64);
};

const version = (
  v: string,
  date: string,
  note: string,
  records: number,
  status: DatasetVersion['status'],
  seed: string,
): DatasetVersion => ({ version: v, date, note, records, checksum: checksum(seed + v), status });

