export const domains: Domain[] = [
  "Women's health",
  'Paediatric health',
  'Maternal & neonatal',
  'Adolescent health',
  'Reproductive health',
];

const clamp = (value: number, min = 0, max = 100) => Math.min(max, Math.max(min, value));
const round1 = (value: number) => Math.round(value * 10) / 10;

const hash = (value: string) => {
  let h = 0;
  for (let i = 0; i < value.length; i += 1) h = (h * 31 + value.charCodeAt(i)) % 997;
  return h;
};

const fieldsFor = (dataset: Dataset) => {
  const universal = ['participant_id', 'age_years', 'sex_at_birth', 'collection_date'];
  const maternal = ['gestational_age_weeks', 'birth_weight_g', 'haemoglobin_g_l', 'parity'];
  const paediatric = ['weight_kg', 'height_cm', 'head_circumference_cm', 'immunisation_status'];
  const mental = ['phq9_score', 'epds_score', 'sleep_hours', 'support_score'];
  if (dataset.domain === 'Paediatric health') return [...universal, ...paediatric];
  if (dataset.domain === "Women's health" || dataset.domain === 'Maternal & neonatal') {
    return [...universal, ...maternal];
  }
  if (dataset.domain === 'Adolescent health') return [...universal, ...mental];
  return [...universal, 'lh_fsh_ratio', 'testosterone_nmol_l', 'amh_pmol_l'];
};

const pick = <T,>(items: T[], seed: number) => items[seed % items.length];

export const buildQualityReport = (dataset: Dataset): QualityReport | null => {
  if (dataset.qualityScore == null) return null;
  const overall = dataset.qualityScore;
  const seed = hash(dataset.id);
  const fields = fieldsFor(dataset);

  const dimensions: Record<QualityDimensionKey, number> = {
    completeness: clamp(overall + 4 - dataset.missingRate, 35, 100),
    validity: clamp(overall - 2 + (seed % 3), 35, 100),
    consistency: clamp(overall - 6 + (seed % 4), 35, 100),
    uniqueness: clamp(100 - dataset.duplicateRate * 8 - 1, 35, 100),
    typeCorrectness: clamp(overall - 1 + (seed % 2), 35, 100),
  };

  const missingRecords = Math.max(1, Math.round((dataset.records * dataset.missingRate) / 100));
  const duplicateRecords = Math.max(1, Math.round((dataset.records * dataset.duplicateRate) / 100));

  const issues: QualityIssue[] = [
    {
      id: `${dataset.id}-Q1`,
      dimension: 'completeness',
      severity: dataset.missingRate > 8 ? 'High' : dataset.missingRate > 4 ? 'Medium' : 'Low',
      field: pick(fields, seed),
      description:
        'Missing values detected. Records are preserved; no imputation has been applied. The field is required by the selected common schema.',
      affectedRecords: missingRecords,
      recommendation: 'Agree an explicit missing-data strategy with the research team before modelling.',
    },
    {
      id: `${dataset.id}-Q2`,
      dimension: 'uniqueness',
      severity: duplicateRecords > DatasetDuplicateThreshold(dataset) ? 'Medium' : 'Low',
      field: 'participant_id',
      description:
        'Repeated participant identifiers found across rows. Rows were retained and flagged, not deleted.',
      affectedRecords: duplicateRecords,
      recommendation: 'Review the duplicate group list and confirm whether repeated visits are intentional.',
    },
    {
      id: `${dataset.id}-Q3`,
      dimension: 'consistency',
      severity: 'Medium',
      field: pick(fields, seed + 3),
      description:
        'Categorical values use inconsistent spellings (for example "Yes", "Y" and "yes"). Majority spelling identified but not rewritten.',
      affectedRecords: Math.round(dataset.records * 0.012),
      recommendation: 'Approve the proposed category normalisation mapping in the transform stage.',
    },
    {
      id: `${dataset.id}-Q4`,
      dimension: 'validity',
      severity: 'Low',
      field: 'collection_date',
      description:
        'A small number of dates could not be parsed with the selected format set. Original values remain unchanged.',
      affectedRecords: Math.round(dataset.records * 0.004) + 3,
      recommendation: 'Confirm the expected date format with the data contributor.',
    },
    {
      id: `${dataset.id}-Q5`,
      dimension: 'validity',
      severity: 'Medium',
      field: pick(fields, seed + 1),
      description:
        'Statistically unusual values were detected. These are flagged for review and are not classified as errors without a clinical validation rule.',
      affectedRecords: Math.round(dataset.records * 0.003) + 2,
      recommendation: 'Validate against clinical plausibility rules before excluding or transforming values.',
    },
  ];

  const grade: QualityReport['grade'] =
    overall >= 90 ? 'Excellent' : overall >= 80 ? 'Good' : overall >= 65 ? 'Fair' : 'Poor';

  return {
    datasetId: dataset.id,
    overall,
    grade,
    dimensions,
    issues,
    assessedAt: dataset.updatedAt,
    rulesVersion: 'Quality rules v0.3.2 (demo)',
    sampleSize: dataset.records,
    method:
      dataset.isLocalPreview
        ? 'Client-side preview from uploaded file profiling. Not a substitute for the backend ETL quality engine.'
        : 'Rule-based demonstration report generated from synthetic dataset statistics.',
  };
};

const DatasetDuplicateThreshold = (dataset: Dataset) =>
  Math.round((dataset.records * 0.01) / 2);

export const buildReadinessReport = (dataset: Dataset): ReadinessReport | null => {
  if (dataset.readinessScore == null) return null;
  const overall = dataset.readinessScore;
  const seed = hash(dataset.id);
  const quality = dataset.qualityScore ?? overall;

  const categories: ReadinessCategory[] = [
    {
      key: 'dataQuality',
      label: 'Data quality',
      score: quality,
      weight: 20,
      note: dataset.isLocalPreview
        ? 'Based on local missing/duplicate profiling.'
        : 'Derived from the latest quality assessment.',
    },
    {
      key: 'featureAvailability',
      label: 'Feature availability',
      score: clamp(overall + 3 - (seed % 5)),
      weight: 15,
      note: `${dataset.columns} source columns mapped to the common schema.`,
    },
    {
      key: 'labelAvailability',
      label: 'Label availability & quality',
      score: dataset.labelColumn ? clamp(overall + 2 - (seed % 7)) : clamp(overall - 28),
      weight: 20,
      note: dataset.labelColumn
        ? `Target column “${dataset.labelColumn}” is present; class balance has not been clinically validated.`
        : 'No labelled target column was supplied for the intended task.',
    },
    {
      key: 'missingValues',
      label: 'Missing values',
      score: clamp(100 - dataset.missingRate * 3.2),
      weight: 10,
      note: `${round1(dataset.missingRate)}% of cells are missing overall.`,
    },
    {
      key: 'metadataCompleteness',
      label: 'Metadata completeness',
      score: dataset.dataDictionaryAvailable ? clamp(80 + (seed % 15)) : clamp(45 + (seed % 10)),
      weight: 10,
      note: dataset.dataDictionaryAvailable
        ? 'Data dictionary, collection period and consent scope documented.'
        : 'No data dictionary supplied; field definitions are incomplete.',
    },
    {
      key: 'documentation',
      label: 'Dataset documentation',
      score: dataset.ethicsApproved ? clamp(72 + (seed % 20)) : clamp(40 + (seed % 12)),
      weight: 10,
      note: dataset.ethicsApproved
        ? 'Ethics approval and study documentation recorded.'
        : 'Ethics approval evidence is missing.',
    },
    {
      key: 'representativeness',
      label: 'Representativeness',
      score: dataset.representativenessScore ?? clamp(overall - 5),
      weight: 10,
      note: 'Based on available demographic coverage only; unavailable attributes are not inferred.',
    },
    {
      key: 'taskSuitability',
      label: 'Task suitability',
      score: clamp(overall + (seed % 9) - 4),
      weight: 5,
      note: `Assessed against: ${dataset.intendedTasks[0] ?? 'no declared task'}.`,
    },
  ];

  const limitations = [
    dataset.labelColumn
      ? `Label “${dataset.labelColumn}” has not been independently clinically validated.`
      : 'No label column is available for supervised learning.',
    dataset.missingRate > 5
      ? `${round1(dataset.missingRate)}% missingness requires an explicit handling strategy.`
      : 'Missingness is low but not zero; document the planned handling.',
    dataset.geography.length < 2
      ? 'Geographic coverage is limited to a single country; external validity is uncertain.'
      : 'Geographic coverage is multi-site but not population-representative.',
    dataset.dataDictionaryAvailable
      ? 'Variable definitions are documented but coding manuals are not version-linked.'
      : 'Field-level definitions are not documented in a data dictionary.',
  ];

  const recommendations = [
    'Approve or correct suggested column mappings before committing a processed version.',
    dataset.labelColumn
      ? 'Hold out a temporally separated validation set for the intended prediction task.'
      : 'Define and document a label extraction rule, then re-run the readiness assessment.',
    'Record exclusion criteria and missing-data handling in the dataset card.',
    'Re-run the AI-readiness assessment whenever a new dataset version is published.',
  ];

  const verdict: ReadinessReport['verdict'] =
    overall >= 80 ? 'Ready' : overall >= 65 ? 'Ready with caveats' : 'Not ready';

  return {
    datasetId: dataset.id,
    task: dataset.intendedTasks[0] ?? 'Research task not declared',
    overall,
    verdict,
    categories,
    limitations,
    recommendations,
    assessedAt: dataset.updatedAt,
    method: 'Rule-based AI-readiness assessment v0.1 (demo). Quality and readiness are scored independently.',
  };
};

const scale = (values: number[], total: number) => {
  const sum = values.reduce((a, b) => a + b, 0);
  return values.map((v) => Math.round((v / sum) * total));
};

export const buildRepresentativenessReport = (dataset: Dataset): RepresentativenessReport | null => {
  if (dataset.representativenessScore == null) return null;
  const seed = hash(dataset.id);
  const total = dataset.records;
  const isPaediatric =
    dataset.domain === 'Paediatric health' || dataset.ageRange.toLowerCase().includes('neonat');
  const isAdolescent = dataset.domain === 'Adolescent health';
  const isMaternal = dataset.domain === 'Maternal & neonatal';

  const adultBands = ['15–19', '20–24', '25–29', '30–34', '35–39', '40–44', '45–49'];
  const childBands = ['0–27 days', '1–11 months', '1–4 years', '5–9 years', '10–12 years', '13–17 years'];
  const teenBands = ['10–12', '13–14', '15–16', '17–19'];

  const ageWeights = isPaediatric
    ? [4, 16, 28, 26, 16, 10]
    : isAdolescent
      ? [26, 28, 26, 20]
      : isMaternal
        ? [14, 20, 20, 18, 14, 9, 5]
        : [8, 19, 24, 22, 16, 8, 3];

  const ageLabels = isPaediatric ? childBands : isAdolescent ? teenBands : adultBands;
  const ageCounts = scale(ageWeights.map((w, i) => w + ((seed + i) % 4) - 1), total);
  const ageBands = ageLabels.map((label, i) => ({ label, value: ageCounts[i] }));

  const pregnancyLabels = isMaternal
    ? ['Trimester 1', 'Trimester 2', 'Trimester 3', 'Postpartum']
    : ["Women's health", 'Reproductive health'].includes(dataset.domain)
      ? ['Not pregnant', 'Trimester 1', 'Trimester 2', 'Trimester 3', 'Postpartum']
      : [];
  const pregnancyStages = pregnancyLabels.map((label, i) => ({
    label,
    value: scale(pregnancyLabels.map((_, j) => 20 + ((seed + j * 3) % 13)), total)[i],
  }));

  const paediatricGroups = isPaediatric || isMaternal
    ? [
        { label: 'Neonates', value: Math.round(total * (isMaternal ? 0.42 : 0.16)) },
        { label: 'Infants (<1y)', value: Math.round(total * 0.2) },
        { label: 'Early childhood (1–4y)', value: Math.round(total * 0.31) },
        { label: 'School age (5–12y)', value: Math.round(total * 0.19) },
      ]
    : [];

  const sites =
    dataset.geography.length > 1
      ? dataset.geography
      : [dataset.geography[0] ?? 'Not recorded'];
  const geoWeights = sites.map((_, i) => 30 + ((seed + i * 7) % 18));
  const geoCounts = scale(geoWeights, total);
  const geography = sites.map((label, i) => ({ label, value: geoCounts[i] }));

  const missingAttributes: RepresentativenessReport['missingAttributes'] = [];
  if (sites.length < 2) {
    missingAttributes.push({
      attribute: 'Sub-national geography',
      detail: 'Only country-level geography is recorded; site or district cannot be derived.',
      action: 'None applied — the attribute is reported as unavailable and is not inferred.',
    });
  }
  if (dataset.domain === 'Paediatric health') {
    missingAttributes.push({
      attribute: 'Pregnancy stage',
      detail: 'Not applicable to this paediatric cohort and not recorded.',
      action: 'Reported explicitly; no value is imputed.',
    });
  }
  missingAttributes.push({
    attribute: 'Socioeconomic index',
    detail: 'Household income or deprivation index is not present in the source file.',
    action: 'Reported as unavailable; consider linking an approved area-level index.',
  });
  if (seed % 3 === 0) {
    missingAttributes.push({
      attribute: 'Ethnicity',
      detail: 'Ethnicity was not collected at source.',
      action: 'Not inferred. Document the resulting limitation in any downstream analysis.',
    });
  }
  if (isAdolescent) {
    missingAttributes.push({
      attribute: 'Guardian consent mode',
      detail: 'The source survey does not distinguish consent pathways.',
      action: 'Reported as unavailable; review governance documentation.',
    });
  }

  return {
    datasetId: dataset.id,
    ageBands,
    pregnancyStages,
    paediatricGroups,
    geography,
    missingAttributes,
    coverageNotes: [
      `Age coverage: ${dataset.ageRange}.`,
      geography.length > 1
        ? `Recorded locations: ${dataset.geography.join(', ')}.`
        : `Only one location is recorded (${geography[0]?.label}); no sub-national detail is available.`,
      isPaediatric
        ? 'Paediatric age bands follow the dataset age definition. Pregnancy attributes are not applicable.'
        : 'Pregnancy-stage distribution is shown only where the source recorded it.',
      'This analysis describes available attributes only. Missing demographic attributes are not inferred.',
    ],
    assessedAt: dataset.updatedAt,
  };
};

export const qualityReports: Record<string, QualityReport> = Object.fromEntries(
  datasets
    .map((dataset) => [dataset.id, buildQualityReport(dataset)] as const)
    .filter((entry): entry is readonly [string, QualityReport] => entry[1] !== null),
);

export const readinessReports: Record<string, ReadinessReport> = Object.fromEntries(
  datasets
    .map((dataset) => [dataset.id, buildReadinessReport(dataset)] as const)
    .filter((entry): entry is readonly [string, ReadinessReport] => entry[1] !== null),
);

export const representativenessReports: Record<string, RepresentativenessReport> = Object.fromEntries(
  datasets
    .map((dataset) => [dataset.id, buildRepresentativenessReport(dataset)] as const)
    .filter((entry): entry is readonly [string, RepresentativenessReport] => entry[1] !== null),
);

